-- Re-cut the two covers that were already posted, to the new default.
--
-- The cropper could only zoom in from 'just covers the frame', so a picture
-- that is not already 16:9 had to lose its overflow - and both of these are
-- stat graphics whose first and last lines were the overflow. The tool now
-- opens showing the whole picture instead, and this brings the two covers
-- that were cut before this up to that default.
--
-- Rendered from each article's own original upload with the same arithmetic
-- the cropper uses: contained in 1200x675 on the colour the page sits on. The
-- originals are untouched, so either one can be cropped differently from the
-- newsroom whenever the writer wants.

INSERT INTO news_images (article_id, content_type, data, uploaded_by)
SELECT 5, 'image/webp', '', a.author_user_id
FROM news_articles a WHERE a.id = 5;

UPDATE news_articles SET cover_image_id = last_insert_rowid() WHERE id = 5;

INSERT INTO news_images (article_id, content_type, data, uploaded_by)
SELECT 4, 'image/webp', '', a.author_user_id
FROM news_articles a WHERE a.id = 4;

UPDATE news_articles SET cover_image_id = last_insert_rowid() WHERE id = 4;
